  const entry = inZone ? price : (gap.lo + gap.hi) / 2;
  let slBase = dir === "bull" ? Math.min(gap.lo, obOverlap ? ob.lo : gap.lo, sw ? sw.level : gap.lo) : Math.max(gap.hi, obOverlap ? ob.hi : gap.hi, sw ? sw.level : gap.hi);
