// ---------- AI scanner: top-down. H4 and H1 give the direction, M15 and M5 give the pullback entry. ----------
// Not only SMC/ICT: trend (EMAs), pullback, RSI turn, candle confirmation, tight ATR stop, and for gold the oil chart.
const AI_MARKETS = ["frxXAUUSD", "frxEURUSD", "frxGBPUSD", "frxUSDJPY", "frxAUDUSD", "frxUSDCAD", "frxGBPJPY", "frxUSDCHF"];
const OIL_SYMBOLS = ["frxBROUSD", "frxWTIUSD"];
