const CONTRACTS = { DIGITUNDER: "Under", DIGITOVER: "Over", DIGITDIFF: "Differs", DIGITMATCH: "Matches", DIGITEVEN: "Even", DIGITODD: "Odd", CALL: "Rise", PUT: "Fall" };
