  "even-odd-auto": { ...DEFAULT_RULES, trigger: { kind: "streak", parity: "even", length: 4 }, contract: { type: "DIGITODD", ticks: 1 }, recovery: { enabled: true, multiplier: 2, maxSteps: 2, trigger: null, contract: null } },
