  const rc = r.recovery && typeof r.recovery === "object" ? r.recovery : {};
  const recovery = { enabled: rc.enabled !== false, multiplier: num(rc.multiplier, 1, 10, 2), maxSteps: int(rc.maxSteps, 0, 8, 3), trigger: rc.trigger ? cleanTrigger(rc.trigger, null) : null, contract: rc.contract ? cleanContract(rc.contract, null) : null };
