async function derivCandles(reqs) {
  const out = {}, errs = {};
  try {
    const res = await fetch("https://api.derivws.com/trading/v1/options/ws/public", { headers: { Upgrade: "websocket" } });
    const ws = Reflect.get(res, "webSocket"); if (!ws) throw new Error("no websocket");
    ws.accept();
    await new Promise((resolve) => {
      const idmap = {}; let left = reqs.length;
      const done = () => { clearTimeout(to); try { ws.close(); } catch {} resolve(); };
      const to = setTimeout(done, 15000);
      ws.addEventListener("message", (ev) => {
        let m; try { m = JSON.parse(ev.data); } catch { return; }
        const k = idmap[m.req_id]; if (!k) return;
        if (m.error) errs[k] = m.error.message || "error";
        else out[k] = (m.candles || []).map((c) => ({ t: c.epoch, o: +c.open, h: +c.high, l: +c.low, c: +c.close }));
        if (--left <= 0) done();
      });
      ws.addEventListener("close", done); ws.addEventListener("error", done);
      reqs.forEach((q, i) => { idmap[i + 1] = q.key; ws.send(JSON.stringify({ ticks_history: q.sym, adjust_start_time: 1, count: 100, end: "latest", style: "candles", granularity: q.g, req_id: i + 1 })); });
    });
  } catch (e) { errs.connect = String(e.message || e); }
  return { out, errs };
}

